use serde_json::Value;
use super::rendering::{truncate_to_width,Text};
use super::render_format::shorten;
use super::renderers_common::{RendererTheme,RenderResultOptions,result_details,result_text,unique,COLLAPSED_HEAD,EXPANDED_HEAD,PATH_BUDGET};
fn diag_severity_key(severity:Option<u64>)->&'static str {match severity {Some(1)=>"error",Some(2)=>"warning",Some(4)=>"dim",_=>"muted"}}
fn diag_severity_char(severity:Option<u64>)->&'static str {match severity {Some(1)=>"E",Some(2)=>"W",Some(3)=>"I",Some(4)=>"H",_=>"?"}}
pub fn render_diagnostics_call(args:&Value,theme:&dyn RendererTheme)->Text {let head=theme.fg("toolTitle",&theme.bold("lsp_diagnostics "));let file=theme.fg("accent",&shorten(args.get("filePath").and_then(Value::as_str).unwrap_or(""),PATH_BUDGET));let sev=args.get("severity").and_then(Value::as_str).filter(|value|!value.is_empty()).map_or_else(String::new,|value|theme.fg("muted",&format!(" [{value}]")));Text::new(format!("{head}{file}{sev}"))}
pub fn render_diagnostics_result(result:&Value,options:RenderResultOptions,theme:&dyn RendererTheme)->Text {
    if options.is_partial {return Text::new(theme.fg("warning","Checking..."));}
    let details=result_details(result);
    if let Some(error)=details.and_then(|d|d.get("error")).and_then(Value::as_str).filter(|e|!e.is_empty()) {let key=if details.and_then(|d|d.get("errorKind")).and_then(Value::as_str)==Some("missing_dependency") {"warning"} else {"error"};let mut lines=vec![theme.fg(key,error.split('\n').next().unwrap_or("error"))];lines.extend(error.split('\n').skip(1).map(|line|theme.fg("dim",&format!("  {line}"))));return Text::new(lines.join("\n"));}
    let Some(details)=details else {return Text::new(theme.fg("muted",result_text(result,0).unwrap_or("")));};
    let total=details.get("totalDiagnostics").and_then(Value::as_u64).unwrap_or(0);if total==0 {return Text::new(theme.fg("success","No diagnostics"));}
    let diagnostics=details.get("diagnostics").and_then(Value::as_array).cloned().unwrap_or_default();let (mut errors,mut warnings,mut infos,mut hints)=(0u64,0u64,0u64,0u64);
    for entry in &diagnostics {match entry.get("diagnostic").and_then(|d|d.get("severity")).and_then(Value::as_u64) {Some(1)=>errors+=1,Some(2)=>warnings+=1,Some(3)=>infos+=1,Some(4)=>hints+=1,_=>{}}}
    let mut badges=Vec::new();
    if errors>0 {badges.push(theme.fg("error",&format!("E:{errors}")));}
    if warnings>0 {badges.push(theme.fg("warning",&format!("W:{warnings}")));}
    if infos>0 {badges.push(theme.fg("muted",&format!("I:{infos}")));}
    if hints>0 {badges.push(theme.fg("dim",&format!("H:{hints}")));}
    let unique_files=unique(diagnostics.clone(),|e|e.get("file").and_then(Value::as_str).unwrap_or("").to_owned());let file_count=unique_files.len();let mut summary=badges.join(" ");summary.push_str(&theme.fg("muted",&format!(" • {file_count} file{}",if file_count==1 {""} else {"s"})));
    if details.get("truncated").and_then(Value::as_bool).unwrap_or(false) {summary.push_str(&theme.fg("warning"," (truncated)"));}
    if !options.expanded {let mut lines=vec![summary];for entry in unique_files.iter().take(COLLAPSED_HEAD) {lines.push(theme.fg("muted",&format!("  {}",shorten(entry.get("file").and_then(Value::as_str).unwrap_or(""),PATH_BUDGET))));}if file_count>COLLAPSED_HEAD {lines.push(theme.fg("dim",&format!("  … {} more files",file_count-COLLAPSED_HEAD)));}return Text::new(lines.join("\n"));}
    let mut grouped:Vec<(String,Vec<Value>)>=Vec::new();for entry in &diagnostics {let file=entry.get("file").and_then(Value::as_str).unwrap_or("").to_owned();let diagnostic=entry.get("diagnostic").cloned().unwrap_or(Value::Null);if let Some(slot)=grouped.iter_mut().find(|(key,_)|key==&file) {slot.1.push(diagnostic);} else {grouped.push((file,vec![diagnostic]));}}
    let mut lines=vec![summary,String::new()];let mut rendered_rows=0usize;'files: for (file,entries) in &grouped {if rendered_rows>=EXPANDED_HEAD {break;}lines.push(theme.fg("accent",&shorten(file,PATH_BUDGET)));for diagnostic in entries {if rendered_rows>=EXPANDED_HEAD {break 'files;}let severity=diagnostic.get("severity").and_then(Value::as_u64);let sev=theme.fg(diag_severity_key(severity),diag_severity_char(severity));let start=diagnostic.get("range").and_then(|r|r.get("start"));let line=start.and_then(|s|s.get("line")).and_then(Value::as_u64).unwrap_or(0);let character=start.and_then(|s|s.get("character")).and_then(Value::as_u64).unwrap_or(0);let at=theme.fg("muted",&format!("{}:{character}",line+1));let msg=theme.fg("toolOutput",&truncate_to_width(diagnostic.get("message").and_then(Value::as_str).unwrap_or(""),160));lines.push(format!("  {sev} {at}  {msg}"));rendered_rows+=1;}}
    if total>EXPANDED_HEAD as u64 {lines.push(theme.fg("dim",&format!("… {} more diagnostics not shown",total-EXPANDED_HEAD as u64)));}Text::new(lines.join("\n"))
}
#[cfg(test)] mod tests {use super::*;use crate::adapter::renderers_common::test_theme::TagTheme;use serde_json::json;
#[test] fn call_marks_title_and_file(){assert_eq!(render_diagnostics_call(&json!({"filePath":"/tmp/a.ts"}),&TagTheme).text,"<toolTitle><b>lsp_diagnostics </b></toolTitle><accent>/tmp/a.ts</accent>");}
#[test] fn call_appends_severity(){assert!(render_diagnostics_call(&json!({"filePath":"/tmp/a.ts","severity":"error"}),&TagTheme).text.ends_with("<muted> [error]</muted>"));}
#[test] fn partial_result_shows_checking(){assert_eq!(render_diagnostics_result(&json!({}),RenderResultOptions {expanded:false,is_partial:true},&TagTheme).text,"<warning>Checking...</warning>");}
#[test] fn missing_details_fall_back_to_content(){assert_eq!(render_diagnostics_result(&json!({"content":[{"type":"text","text":"plain"}]}),RenderResultOptions::default(),&TagTheme).text,"<muted>plain</muted>");}
#[test] fn missing_dependency_warns_with_continuation(){let result=json!({"details":{"error":"missing server\ninstall it","errorKind":"missing_dependency"}});assert_eq!(render_diagnostics_result(&result,RenderResultOptions::default(),&TagTheme).text,"<warning>missing server</warning>\n<dim>  install it</dim>");}
#[test] fn empty_diagnostics_reports_success(){assert_eq!(render_diagnostics_result(&json!({"details":{"totalDiagnostics":0,"diagnostics":[]}}),RenderResultOptions::default(),&TagTheme).text,"<success>No diagnostics</success>");}
#[test] fn collapsed_summary_counts_diagnostics_and_files(){let r=json!({"details":{"totalDiagnostics":2,"diagnostics":[{"file":"/a","diagnostic":{"severity":1}},{"file":"/b","diagnostic":{"severity":2}}]}});assert!(render_diagnostics_result(&r,RenderResultOptions::default(),&TagTheme).text.starts_with("<error>E:1</error> <warning>W:1</warning><muted> • 2 files</muted>"));}
#[test] fn expanded_renders_diagnostic_rows(){let r=json!({"details":{"totalDiagnostics":1,"diagnostics":[{"file":"/a","diagnostic":{"severity":1,"range":{"start":{"line":0,"character":2}},"message":"boom"}}]}});assert!(render_diagnostics_result(&r,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text.contains("<toolOutput>boom</toolOutput>"));}
#[test] fn collapsed_summary_marks_more_files_and_truncation(){let result=json!({"details":{"totalDiagnostics":4,"truncated":true,"diagnostics":[{"file":"/a","diagnostic":{"severity":1}},{"file":"/b","diagnostic":{"severity":1}},{"file":"/c","diagnostic":{"severity":1}},{"file":"/d","diagnostic":{"severity":1}}]}});assert_eq!(render_diagnostics_result(&result,RenderResultOptions::default(),&TagTheme).text,"<error>E:4</error><muted> • 4 files</muted><warning> (truncated)</warning>\n<muted>  /a</muted>\n<muted>  /b</muted>\n<muted>  /c</muted>\n<dim>  … 1 more files</dim>");}
#[test] fn expanded_groups_rows_by_file(){let result=json!({"details":{"totalDiagnostics":2,"truncated":false,"diagnostics":[{"file":"/a","diagnostic":{"severity":1,"range":{"start":{"line":0,"character":2}},"message":"boom"}},{"file":"/a","diagnostic":{"severity":2,"range":{"start":{"line":3,"character":0}},"message":"warn"}}]}});let text=render_diagnostics_result(&result,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text;assert_eq!(text,"<error>E:1</error> <warning>W:1</warning><muted> • 1 file</muted>\n\n<accent>/a</accent>\n  <error>E</error> <muted>1:2</muted>  <toolOutput>boom</toolOutput>\n  <warning>W</warning> <muted>4:0</muted>  <toolOutput>warn</toolOutput>");}
#[test] fn expanded_notes_rows_beyond_the_head(){let diagnostics=(0..22).map(|index|json!({"file":"/a","diagnostic":{"severity":1,"range":{"start":{"line":index,"character":0}},"message":"m"}})).collect::<Vec<_>>();let result=json!({"details":{"totalDiagnostics":22,"truncated":false,"diagnostics":diagnostics}});let text=render_diagnostics_result(&result,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text;assert!(text.contains("<dim>… 2 more diagnostics not shown</dim>"));}
}
